  shouldTriggerUnreadNotification,
  totalUnreadCount,
  GITHUB_UPDATE_API_URL,
  GITHUB_UPDATE_MANIFEST_URL,
  GITHUB_UPDATE_CDN_URL,
  GITHUB_UPDATE_ZIP_URL,
  isUpdateAvailable,
};

