    try {
      mainWindow.setOverlayIcon(createCircleIcon(239, 43, 45, false), `${label} thông báo mới`);
    } catch {}
  } else {
    mainWindow.setTitle('Social Hub');
    try {
      mainWindow.setOverlayIcon(null, '');
    } catch {}
